using Microsoft.EntityFrameworkCore;using MyExpenseTracker.Api.Models;namespace MyExpenseTracker.Api.Data;public class AppDbContext(DbContextOptions<AppDbContext> o):DbContext(o){public DbSet<AppUser> Users=>Set<AppUser>();public DbSet<Account> Accounts=>Set<Account>();public DbSet<Transaction> Transactions=>Set<Transaction>();public DbSet<Budget> Budgets=>Set<Budget>();protected override void OnModelCreating(ModelBuilder m){m.Entity<AppUser>().HasIndex(x=>x.UserName).IsUnique();m.Entity<AppUser>().Property(x=>x.PasswordHash).HasMaxLength(500);m.Entity<Account>().Property(x=>x.Name).HasMaxLength(100).IsRequired();m.Entity<Account>().Property(x=>x.OpeningBalance).HasPrecision(18,2);m.Entity<Transaction>().Property(x=>x.Amount).HasPrecision(18,2);m.Entity<Transaction>().Property(x=>x.Category).HasMaxLength(50).IsRequired();m.Entity<Transaction>().Property(x=>x.Description).HasMaxLength(1000).IsRequired();m.Entity<Budget>().Property(x=>x.Amount).HasPrecision(18,2);m.Entity<Budget>().HasIndex(x=>new{x.Year,x.Month,x.Category}).IsUnique();}}